import{_ as e,o as t,c as o,a2 as l}from"./chunks/framework.CCCdsIgc.js";const u=JSON.parse('{"title":"连接器","description":"","frontmatter":{},"headers":[],"relativePath":"guide/connectors.md","filePath":"guide/connectors.md"}'),r={name:"guide/connectors.md"};function i(n,a,s,c,d,h){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="连接器" tabindex="-1">连接器 <a class="header-anchor" href="#连接器" aria-label="Permalink to &quot;连接器&quot;">​</a></h1><p>连接器让 AI 直接操作公司用的在线服务，比如腾讯文档、企业微信、飞书、钉钉。它基于 MCP（各家厂商给 AI 开放能力的标准接口）。</p><h2 id="连接" tabindex="-1">连接 <a class="header-anchor" href="#连接" aria-label="Permalink to &quot;连接&quot;">​</a></h2><ol><li>侧栏「<strong>连接器</strong>」里能看到 IT 上架的服务，每个都有介绍和「试试这样用」的示例；</li><li>点「<strong>连接</strong>」： <ul><li>有的由 IT 统一配好账号，点一下就连上；</li><li>有的要填自己的账号或密钥；</li><li>有的会打开浏览器，登录你自己的账号授权。</li></ul></li><li>连上后，在办事模式里就能直接说「把这张表发到企业微信群」这类话。</li></ol><h2 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to &quot;安全&quot;">​</a></h2><ul><li>只能用 IT 上架的连接器，员工不能自己添加；</li><li>通过连接器<strong>写入、发送、删除</strong>的操作默认都要你确认；厂商标为高危的操作不能设成「以后自动」；</li><li>连接器的日志会把账号、令牌打码，不会写进对话。</li></ul><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>连接器面板会显示每个连接的延迟和状态。本机运行的连接器意外退出时会自动重启，连不上时会标出来并说明原因。</p>',8)])])}const p=e(r,[["render",i]]);export{u as __pageData,p as default};
